// @ts-nocheck
export const GPTMAKER_CHAT='https://app.gptmaker.ai/widget/3FB126EEAA8EC3273F6F26205F86C1A5/iframe';
const CONSENT='sky-v2-gptmaker-2026-10-23';
const WA='https://wa.me/5551999938323';
let contactSession=false,sessionPending=null;
const node=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
function link(text,href,cls){const a=node('a',cls,text);a.href=href;a.target='_blank';a.rel='noopener noreferrer';return a}
async function _unused_contactApi(path,data,method='POST'){
 const r=await fetch('/api/sky/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-Sky-Request':'1'},...(data?{body:JSON.stringify(data)}:{})});
 let d;try{d=await r.json()}catch{throw Error('Pedido indisponível. Fale com Alan pelo WhatsApp.')}
 if(!r.ok){if(r.status===401)contactSession=false;throw Error(d.error||'Não foi possível concluir.')}return d;
}
async function ensureContactSession(){if(contactSession)return;if(!sessionPending)sessionPending=contactApi('session',{consent:true,consentVersion:CONSENT}).then(()=>{contactSession=true}).finally(()=>{sessionPending=null});await sessionPending;}
export function mountSkyChat(root,{tall=false}={}){
 root.className='sky-chat sky-maker'+(tall?' sky-chat-tall':'');
 root.innerHTML=`<header class="sky-chat-head"><span class="ai-mascot" role="img" aria-label="Sky IA em cadeira flutuante"><span class="ai-mascot-aura" aria-hidden="true"></span><img class="ai-mascot-art" src="/assets/ai-robot-animated.svg" alt="" width="116" height="132"></span><div><strong>Sky IA</strong><span class="sky-status">● Atendimento com IA</span><small>Assistente de Alan Alves · GPT Maker</small></div></header><div class="sky-maker-body"><section class="sky-maker-start"><p>Olá! Vamos tirar sua ideia do papel?</p><p>Converse com a Sky sobre seu site, sistema ou automação.</p><label class="sky-consent"><input type="checkbox"><span>Autorizo carregar o chat do GPT Maker e processar minhas mensagens para este atendimento. Não envie dados sensíveis. O histórico é gerenciado pelo GPT Maker.</span></label><button type="button" class="sky-primary sky-maker-start-btn">Iniciar conversa com Sky</button><p class="sky-maker-warning" role="status"></p></section></div><div class="sky-contact-row"></div><section class="sky-lead-panel" hidden></section><div class="sky-privacy"><span>IA pode cometer erros. Orçamentos confirmados por Alan.</span><button type="button" class="sky-reset">Apagar pedido de contato</button></div>`;
 const host=root.querySelector('.sky-maker-body'),start=root.querySelector('.sky-maker-start-btn'),warning=root.querySelector('.sky-maker-warning'),consent=root.querySelector('.sky-consent input'),lead=root.querySelector('.sky-lead-panel');
 start.onclick=()=>{if(!consent.checked){warning.textContent='Marque a autorização para carregar o chat.';return}const frame=node('iframe','sky-maker-frame');frame.src=GPTMAKER_CHAT;frame.title='Conversa com Sky IA — GPT Maker';frame.referrerPolicy='no-referrer';frame.setAttribute('sandbox','allow-scripts allow-forms allow-same-origin allow-popups allow-popups-to-escape-sandbox');frame.setAttribute('allow','microphone \'none\'; camera \'none\'');host.replaceChildren(frame);root.classList.add('sky-maker-loaded');};
 const toggle=node('button','sky-outline','Solicitar orçamento');toggle.type='button';root.querySelector('.sky-contact-row').append(toggle,link('Falar com Alan ↗',WA,'sky-wa'),link('Abrir chat ↗',GPTMAKER_CHAT,'sky-outline'));
 toggle.onclick=()=>{lead.hidden=!lead.hidden;root.classList.toggle('sky-maker-show-lead',!lead.hidden);if(!lead.hidden)lead.querySelector('input')?.focus()};
 lead.innerHTML=`<h3>Vamos conversar sobre seu projeto</h3><p>Preencha apenas se quiser receber contato do Alan.</p><form class="sky-lead-form"><label>Seu nome<input name="name" autocomplete="name" minlength="2" maxlength="80" required></label><label>WhatsApp com DDD<input name="phone" inputmode="tel" autocomplete="tel" placeholder="(51) 99993-8323" maxlength="20" required></label><label>Seu projeto<textarea name="project" minlength="10" maxlength="2000" rows="3" required></textarea></label><div class="sky-honeypot" aria-hidden="true"><label>Site<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="sky-consent"><input name="consent" type="checkbox" required><span>Autorizo Alan Alves a usar estes dados por 90 dias (exclusão na próxima limpeza automática) e me contatar sobre este projeto. Posso solicitar exclusão pelo WhatsApp.</span></label><button type="submit" class="sky-primary">Salvar pedido de contato</button><p class="sky-lead-result" role="status"></p></form>`;
 lead.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget,result=f.querySelector('.sky-lead-result');if(!f.elements.consent.checked){result.textContent='Autorize o contato para continuar.';return}const v=Object.fromEntries(new FormData(f));const msg=`Olá Alan! Meu nome é ${v.name}.\nWhatsApp: ${v.phone}\nProjeto: ${v.project}`;const href=WA+'?text='+encodeURIComponent(msg);contactSession=true;result.replaceChildren(node('span','','Pedido preparado. A mensagem de WhatsApp só será enviada quando você abrir o link e confirmar o envio. '),link('Continuar no WhatsApp ↗',href,'sky-wa'));};
 root.querySelector('.sky-reset').onclick=()=>{if(!contactSession){root.querySelector('.sky-privacy span').textContent='Nenhum pedido foi salvo nesta sessão. O histórico do chat é gerenciado pelo GPT Maker.';return}if(!window.confirm('Apagar o pedido de contato associado a esta sessão? O histórico do GPT Maker não será alterado.'))return;contactSession=false;lead.querySelector('form').reset();lead.querySelector('.sky-lead-result').textContent='Pedido de contato apagado.'};
 return()=>{host.querySelector('iframe')?.remove()};
}
export function mountFloatingSky(){
 if(document.querySelector('.sky-launcher'))return;
 const launcher=node('button','sky-launcher');launcher.type='button';launcher.setAttribute('aria-label','Conversar com Sky IA');launcher.setAttribute('aria-expanded','false');launcher.setAttribute('aria-controls','sky-floating');launcher.innerHTML='<img src="/assets/ai-robot-animated.svg" alt="" width="90" height="106"><span>Sky IA</span>';
 const panel=node('section','sky-floating');panel.id='sky-floating';panel.hidden=true;panel.setAttribute('aria-label','Atendimento Sky IA');const close=node('button','sky-close','×');close.type='button';close.setAttribute('aria-label','Fechar conversa');const host=node('div');panel.append(close,host);document.body.append(panel,launcher);mountSkyChat(host,{tall:true});
 const open=v=>{panel.hidden=!v;launcher.setAttribute('aria-expanded',String(v));if(v)close.focus();else launcher.focus()};launcher.onclick=()=>open(panel.hidden);close.onclick=()=>open(false);panel.addEventListener('keydown',e=>{if(e.key==='Escape')open(false)});
}
